static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;
  DATA_TYPE eps = SCALAR_VAL(0.1);
  const DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int i = 0;
      for (; i + 4 <= _PB_N; i += 4)
	{
	  sum += data[i][j];
	  sum += data[i + 1][j];
	  sum += data[i + 2][j];
	  sum += data[i + 3][j];
	}
      for (; i < _PB_N; i++)
	sum += data[i][j];
      mean[j] = sum / float_n;
    }

  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int i = 0;
      for (; i + 4 <= _PB_N; i += 4)
	{
	  DATA_TYPE d0 = data[i][j] - mean[j];
	  DATA_TYPE d1 = data[i + 1][j] - mean[j];
	  DATA_TYPE d2 = data[i + 2][j] - mean[j];
	  DATA_TYPE d3 = data[i + 3][j] - mean[j];
	  sum += d0 * d0;
	  sum += d1 * d1;
	  sum += d2 * d2;
	  sum += d3 * d3;
	}
      for (; i < _PB_N; i++)
	{
	  DATA_TYPE d = data[i][j] - mean[j];
	  sum += d * d;
	}
      stddev[j] = SQRT_FUN(sum / float_n);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= sqrt_float_n * stddev[j];
      }

  for (i = 0; i < _PB_M - 1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i + 1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          int k = 0;
          for (; k + 4 <= _PB_N; k += 4)
            {
              sum += data[k][i] * data[k][j];
              sum += data[k + 1][i] * data[k + 1][j];
              sum += data[k + 2][i] * data[k + 2][j];
              sum += data[k + 3][i] * data[k + 3][j];
            }
          for (; k < _PB_N; k++)
            sum += data[k][i] * data[k][j];
          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }
  corr[_PB_M - 1][_PB_M - 1] = SCALAR_VAL(1.0);
#pragma endscop
}

