static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for (t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];

      for (i = 1; i < _PB_NX; i++)
	{
	  int j = 0;
	  for (; j + 4 <= _PB_NY; j += 4)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(4);
	      vfloat64m1_t v_ey = __riscv_vle64_v_f64m1(&ey[i][j], vl);
	      vfloat64m1_t v_hz_cur = __riscv_vle64_v_f64m1(&hz[i][j], vl);
	      vfloat64m1_t v_hz_prev = __riscv_vle64_v_f64m1(&hz[i - 1][j], vl);
	      vfloat64m1_t v_diff = __riscv_vfsub_vv_f64m1(v_hz_cur, v_hz_prev, vl);
	      vfloat64m1_t v_half = __riscv_vfmul_vf_f64m1(v_diff, SCALAR_VAL(0.5), vl);
	      v_ey = __riscv_vfsub_vv_f64m1(v_ey, v_half, vl);
	      __riscv_vse64_v_f64m1(&ey[i][j], v_ey, vl);
	    }
	  for (; j < _PB_NY; j++)
	    ey[i][j] = ey[i][j] - SCALAR_VAL(0.5) * (hz[i][j] - hz[i - 1][j]);
	}

      for (i = 0; i < _PB_NX; i++)
	{
	  int j = 1;
	  for (; j + 4 <= _PB_NY; j += 4)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(4);
	      vfloat64m1_t v_ex = __riscv_vle64_v_f64m1(&ex[i][j], vl);
	      vfloat64m1_t v_hz_cur = __riscv_vle64_v_f64m1(&hz[i][j], vl);
	      vfloat64m1_t v_hz_prev = __riscv_vle64_v_f64m1(&hz[i][j - 1], vl);
	      vfloat64m1_t v_diff = __riscv_vfsub_vv_f64m1(v_hz_cur, v_hz_prev, vl);
	      vfloat64m1_t v_half = __riscv_vfmul_vf_f64m1(v_diff, SCALAR_VAL(0.5), vl);
	      v_ex = __riscv_vfsub_vv_f64m1(v_ex, v_half, vl);
	      __riscv_vse64_v_f64m1(&ex[i][j], v_ex, vl);
	    }
	  for (; j < _PB_NY; j++)
	    ex[i][j] = ex[i][j] - SCALAR_VAL(0.5) * (hz[i][j] - hz[i][j - 1]);
	}

      for (i = 0; i < _PB_NX - 1; i++)
	{
	  int j = 0;
	  for (; j + 4 <= _PB_NY - 1; j += 4)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(4);
	      vfloat64m1_t v_hz = __riscv_vle64_v_f64m1(&hz[i][j], vl);
	      vfloat64m1_t v_ex_r = __riscv_vle64_v_f64m1(&ex[i][j + 1], vl);
	      vfloat64m1_t v_ex_l = __riscv_vle64_v_f64m1(&ex[i][j], vl);
	      vfloat64m1_t v_ey_r = __riscv_vle64_v_f64m1(&ey[i + 1][j], vl);
	      vfloat64m1_t v_ey_l = __riscv_vle64_v_f64m1(&ey[i][j], vl);

	      vfloat64m1_t v_ex_diff = __riscv_vfsub_vv_f64m1(v_ex_r, v_ex_l, vl);
	      vfloat64m1_t v_ey_diff = __riscv_vfsub_vv_f64m1(v_ey_r, v_ey_l, vl);
	      vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_ex_diff, v_ey_diff, vl);
	      vfloat64m1_t v_term = __riscv_vfmul_vf_f64m1(v_sum, SCALAR_VAL(0.7), vl);
	      v_hz = __riscv_vfsub_vv_f64m1(v_hz, v_term, vl);
	      __riscv_vse64_v_f64m1(&hz[i][j], v_hz, vl);
	    }
	  for (; j < _PB_NY - 1; j++)
	    hz[i][j] = hz[i][j] - SCALAR_VAL(0.7) * (ex[i][j + 1] - ex[i][j] +
						      ey[i + 1][j] - ey[i][j]);
	}
    }

#pragma endscop
}

