static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;
  const int N = _PB_N;

#pragma scop
  for (k = 0; k < N; k++)
    {
      const DATA_TYPE *rowk = path[k];
      for (i = 0; i < N; i++)
	{
	  DATA_TYPE *rowi = path[i];
	  const DATA_TYPE dik = rowi[k];

	  int j = 0;
	  while (j < N)
	    {
	      size_t vl = __riscv_vsetvl_e32m8((size_t)(N - j));

	      vint32m8_t v_ij = __riscv_vle32_v_i32m8((const int32_t *)(rowi + j), vl);
	      vint32m8_t v_kj = __riscv_vle32_v_i32m8((const int32_t *)(rowk + j), vl);
	      vint32m8_t v_dik = __riscv_vmv_v_x_i32m8((int32_t)dik, vl);
	      vint32m8_t v_sum = __riscv_vadd_vv_i32m8(v_dik, v_kj, vl);
	      vint32m8_t v_min = __riscv_vmin_vv_i32m8(v_ij, v_sum, vl);

	      __riscv_vse32_v_i32m8((int32_t *)(rowi + j), v_min, vl);
	      j += (int)vl;
	    }
	}
    }
#pragma endscop
}

