static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
      C[i][j] *= beta;

    for (k = 0; k < _PB_NK; k++) {
      const DATA_TYPE aijk = alpha * A[i][k];
      int j = 0;

      for (; j + 4 <= _PB_NJ; j += 4) {
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], 4);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][j], 4);
        vfloat64m1_t vm = __riscv_vfmul_vf_f64m1(vb, aijk, 4);
        vc = __riscv_vfadd_vv_f64m1(vc, vm, 4);
        __riscv_vse64_v_f64m1(&C[i][j], vc, 4);
      }

      for (; j < _PB_NJ; j++) {
        C[i][j] += aijk * B[k][j];
      }
    }
  }
#pragma endscop
}

