static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;
  const int inner_n = n - 2;
  const double c = 0.33333;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      int i = 1;
      while (i <= inner_n)
	{
	  size_t vl = __riscv_vsetvl_e64m1((size_t)(inner_n - i + 1));

	  vfloat64m1_t va_l = __riscv_vle64_v_f64m1((const double*)(A + i - 1), vl);
	  vfloat64m1_t va_c = __riscv_vle64_v_f64m1((const double*)(A + i), vl);
	  vfloat64m1_t va_r = __riscv_vle64_v_f64m1((const double*)(A + i + 1), vl);

	  vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(va_l, va_c, vl);
	  vs = __riscv_vfadd_vv_f64m1(vs, va_r, vl);
	  vfloat64m1_t vb = __riscv_vfmul_vf_f64m1(vs, c, vl);

	  __riscv_vse64_v_f64m1((double*)(B + i), vb, vl);
	  i += (int)vl;
	}

      i = 1;
      while (i <= inner_n)
	{
	  size_t vl = __riscv_vsetvl_e64m1((size_t)(inner_n - i + 1));

	  vfloat64m1_t vb_l = __riscv_vle64_v_f64m1((const double*)(B + i - 1), vl);
	  vfloat64m1_t vb_c = __riscv_vle64_v_f64m1((const double*)(B + i), vl);
	  vfloat64m1_t vb_r = __riscv_vle64_v_f64m1((const double*)(B + i + 1), vl);

	  vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(vb_l, vb_c, vl);
	  vs = __riscv_vfadd_vv_f64m1(vs, vb_r, vl);
	  vfloat64m1_t va = __riscv_vfmul_vf_f64m1(vs, c, vl);

	  __riscv_vse64_v_f64m1((double*)(A + i), va, vl);
	  i += (int)vl;
	}
    }
#pragma endscop
}

