static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  const int inner = _PB_N - 1;
  const DATA_TYPE c02 = SCALAR_VAL(0.2);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < inner; i++)
	{
	  int j = 1;
	  for (; j < inner; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(inner - j));

	      const DATA_TYPE *a_cur = &A[i][j];
	      const DATA_TYPE *a_left = &A[i][j - 1];
	      const DATA_TYPE *a_right = &A[i][j + 1];
	      const DATA_TYPE *a_down = &A[i + 1][j];
	      const DATA_TYPE *a_up = &A[i - 1][j];

	      vfloat64m1_t va_cur = __riscv_vle64_v_f64m1(a_cur, vl);
	      vfloat64m1_t va_left = __riscv_vle64_v_f64m1(a_left, vl);
