	      vfloat64m1_t va_up = __riscv_vle64_v_f64m1(a_up, vl);

	      vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(va_cur, va_left, vl);
	      vs = __riscv_vfadd_vv_f64m1(vs, va_right, vl);
	      vs = __riscv_vfadd_vv_f64m1(vs, va_down, vl);
	      vs = __riscv_vfadd_vv_f64m1(vs, va_up, vl);
	      vs = __riscv_vfmul_vf_f64m1(vs, c02, vl);

	      DATA_TYPE *b_cur = &B[i][j];
	      __riscv_vse64_v_f64m1(b_cur, vs, vl);

	      j += (int)vl;
	    }
	}

      for (i = 1; i < inner; i++)
	{
	  int j = 1;
	  for (; j < inner; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(inner - j));

	      const DATA_TYPE *b_cur = &B[i][j];
	      const DATA_TYPE *b_left = &B[i][j - 1];
	      const DATA_TYPE *b_right = &B[i][j + 1];
	      const DATA_TYPE *b_down = &B[i + 1][j];
	      const DATA_TYPE *b_up = &B[i - 1][j];

	      vfloat64m1_t vb_cur = __riscv_vle64_v_f64m1(b_cur, vl);
	      vfloat64m1_t vb_left = __riscv_vle64_v_f64m1(b_left, vl);
	      vfloat64m1_t vb_right = __riscv_vle64_v_f64m1(b_right, vl);
	      vfloat64m1_t vb_down = __riscv_vle64_v_f64m1(b_down, vl);
	      vfloat64m1_t vb_up = __riscv_vle64_v_f64m1(b_up, vl);

	      vfloat64m1_t vs = __riscv_vfadd_vv_f64m1(vb_cur, vb_left, vl);
	      vs = __riscv_vfadd_vv_f64m1(vs, vb_right, vl);
	      vs = __riscv_vfadd_vv_f64m1(vs, vb_down, vl);
	      vs = __riscv_vfadd_vv_f64m1(vs, vb_up, vl);
	      vs = __riscv_vfmul_vf_f64m1(vs, c02, vl);

	      DATA_TYPE *a_cur = &A[i][j];
	      __riscv_vse64_v_f64m1(a_cur, vs, vl);

	      j += (int)vl;
	    }
	}
    }
#pragma endscop
}

