#pragma scop
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++)
    {
      temp2 = 0;
      for (k = 0; k < i; k++)
	{
	  DATA_TYPE aik = A[i][k];
	  C[k][j] += alpha * B[i][j] * aik;
	  temp2 += B[k][j] * aik;
	}
      C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i] + alpha * temp2;
    }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    int jlim = i + 1;

    for (j = 0; j < jlim; j++) {
      C[i][j] *= beta;
    }

    for (k = 0; k < _PB_M; k++) {
      int j = 0;
      for (; j + 4 <= jlim; j += 4) {
        DATA_TYPE c0 = C[i][j];
        DATA_TYPE c1 = C[i][j + 1];
        DATA_TYPE c2 = C[i][j + 2];
        DATA_TYPE c3 = C[i][j + 3];

        DATA_TYPE a0 = A[j][k];
        DATA_TYPE a1 = A[j + 1][k];
        DATA_TYPE a2 = A[j + 2][k];
        DATA_TYPE a3 = A[j + 3][k];

        DATA_TYPE b0 = B[j][k];
        DATA_TYPE b1 = B[j + 1][k];
        DATA_TYPE b2 = B[j + 2][k];
        DATA_TYPE b3 = B[j + 3][k];

        c0 += a0 * alpha * b0 + b0 * alpha * A[i][k];
        c1 += a1 * alpha * b1 + b1 * alpha * A[i][k];
        c2 += a2 * alpha * b2 + b2 * alpha * A[i][k];
        c3 += a3 * alpha * b3 + b3 * alpha * A[i][k];

        C[i][j] = c0;
        C[i][j + 1] = c1;
        C[i][j + 2] = c2;
        C[i][j + 3] = c3;
      }
      for (; j < jlim; j++) {
        C[i][j] += A[j][k] * alpha * B[i][k] + B[j][k] * alpha * A[i][k];
      }
    }
  }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    int j = 0;
    for (; j <= i; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(i - j + 1));
      vfloat64m1_t v = __riscv_vle64_v_f64m1((const double *)(C[i] + j), vl);
      v = __riscv_vfmul_vf_f64m1(v, beta, vl);
      __riscv_vse64_v_f64m1((double *)(C[i] + j), v, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_M; k++) {
      j = 0;
      for (; j <= i; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i - j + 1));

        vfloat64m1_t vc = __riscv_vle64_v_f64m1((const double *)(C[i] + j), vl);
        vfloat64m1_t va_i = __riscv_vle64_v_f64m1((const double *)(A[i] + k), vl);
        vfloat64m1_t va_j = __riscv_vle64_v_f64m1((const double *)(A[j] + k), vl);

        vfloat64m1_t vmul = __riscv_vfmul_vv_f64m1(va_i, va_j, vl);
        vmul = __riscv_vfmul_vf_f64m1(vmul, alpha, vl);
        vc = __riscv_vfadd_vv_f64m1(vc, vmul, vl);

        __riscv_vse64_v_f64m1((double *)(C[i] + j), vc, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
      x[i] = x[i] / L[i][i];
    }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE sum = 0;
      for (k = i + 1; k < _PB_M; k++) {
        sum += A[k][i] * B[k][j];
      }
      B[i][j] += sum;
      B[i][j] = alpha * B[i][j];
    }
  }
#pragma endscop
}
